    styleCss: "/* roof repair west new york nj supplemental guide block */\n/* emergency roof repair, roof leak repair, shingle repair, flat roof repair */\n/* roof repair services, roof repair contractor, roof repair company, nj roof repair */\n/* roof repair nj, roof repair west new york, roof repair west new york nj, roof repair west new york nj repairs */\n/* roof maintenance, roof restoration west new york nj, roof replacement west new york nj */\n/* licensed roof repair, insured roof repair, professional roof repair, affordable roof repair */\n/* quick roof repair, same day roof repair, roof fix west new york nj, wny roof repair */\n/* roof shingle repair, roof repairs, roofing repair, roof repair professionals, roof repair experts */\n/* west new york, new york nj, ny nj, west nj, new york, jersey city quality roofing hudson county */\ndetails > summary { cursor: pointer; }\ndetails span { letter-spacing: 0.01em; }\n@media (max-width: 640px) { details span { margin-right: 0.5rem; } }",
